export function sprayTag(c,text,x,y,size,color,random){c.save();c.translate(x,y);c.lineCap='round';c.lineJoin='round';let cursor=0;for(const ch of text.toUpperCase()){if(ch===' '){cursor+=size*.42;continue;}const strokes=letters[ch];if(!strokes)continue;const dx=cursor+(random()-.5)*size*.07,dy=(random()-.5)*size*.1,lean=.08+random()*.16,stretch=.88+random()*.22;const paths=strokes.map(stroke=>stroke.map(([a,b])=>[dx+(a+(1-b)*lean)*size,dy+b*size*stretch]));for(const [width,ink]of [[size*.22,'#26332db0'],[size*.13,color+'d9']]){c.strokeStyle=ink;c.lineWidth=width;for(const points of paths){c.beginPath();points.forEach(([px,py],i)=>i?c.lineTo(px,py):c.moveTo(px,py));c.stroke();}}if(random()<.32){c.strokeStyle=color+'90';c.lineWidth=size*.035;c.beginPath();c.moveTo(dx+size*.3,dy+size*.75);c.lineTo(dx+size*.29,dy+size*(1.2+random()*.35));c.stroke();}cursor+=size*(.80+random()*.13);}c.strokeStyle=color+'a0';c.lineWidth=size*.05;c.beginPath();c.moveTo(-size*.1,size*1.25);c.quadraticCurveTo(cursor*.5,size*(1.05+random()*.2),cursor+size*.1,size*1.15);c.stroke();for(let i=0;i<text.length*3;i++){c.fillStyle=color+'28';c.beginPath();c.arc(random()*cursor,(random()-.1)*size*1.5,.3+random()*size*.018,0,Math.PI*2);c.fill();}c.restore();}
